// 摸牌（跳过亮牌）
drawCard(playerId) {
    if (this.gameState.deck.length === 0) {
        return null; // 流局
    }

    // 检查是否遇到亮牌（亮牌在牌堆末尾）
    // 亮牌始终保留在牌堆中不发给玩家
    if (this.gameState.shownCardIndex >= 0 &&
        this.gameState.shownCardIndex === this.gameState.deck.length - 1) {
        console.log(`抓牌时跳过亮牌: ${cardName(this.gameState.shownCard)}，亮牌保留`);
        this.gameState.shownCardSkipped = true;
        // 暂存亮牌，弹出下一张给玩家，再把亮牌放回去
        const shownCard = this.gameState.deck.pop(); // 弹出亮牌
        const card = this.gameState.deck.pop();      // 弹出实际要抓的牌
        if (shownCard) {
            this.gameState.deck.push(shownCard);      // 亮牌放回末尾
        }
        this.gameState.shownCardIndex = -1; // 亮牌已处理，不再跟踪索引

        if (card) {
        this.gameState.hands[playerId].push(card);
        this.gameState.lastDrawn = card;
        this.sortHand(playerId);

        // 更新亮牌索引（还没跳过的话）
        if (!this.gameState.shownCardSkipped && this.gameState.shownCardIndex >= 0) {
            this.gameState.shownCardIndex--;
        }

        // 更新牌墙状态
        this.updateWallState();

        // 广播摸牌动画
        this.broadcastDrawAnimation(playerId);
    }
    return card;
}

// 广播摸牌动画
broadcastDrawAnimation(playerId) {
    const player = this.players.get(playerId);
    const seatNum = player ? player.seatNum : 0;

    // 包含亮牌信息
