// 更新万能牌
if (gameState.wildCard) {
    const wildCardDisplay = document.getElementById('wildCardDisplay');
    const imgSrc = getCardImageSrc(gameState.wildCard);
    if (imgSrc) {
        wildCardDisplay.innerHTML = `<img src="${imgSrc}" style="width:28px;height:36px;vertical-align:middle;" alt="${getCardDisplayName(gameState.wildCard)}">`;
    } else {
        wildCardDisplay.textContent = getCardDisplayName(gameState.wildCard);
    }
}

// 更新亮牌显示
if (gameState.shownCard) {
    currentShownCard = gameState.shownCard;
    // 同步亮牌位置信息
    if (gameState.drawInfo) {
        currentShownInfo = {
            direction: gameState.drawInfo.shownDirection,
            pile: gameState.drawInfo.shownPile
        };
    }
    // 如果亮牌已被跳过，在中央展示
    if (gameState.shownCardSkipped) {
        currentShownInfo = { ...currentShownInfo, movedToCenter: true };
        const shownCardDisplay = document.getElementById('shownCardDisplay');
        const shownCardImg = document.getElementById('shownCardImg');
        if (shownCardDisplay) {
            shownCardDisplay.style.display = 'block';
            const imgSrc = getCardImageSrc(currentShownCard);
            if (imgSrc) {
                shownCardImg.innerHTML = `<img src="${imgSrc}" alt="${getCardDisplayName(currentShownCard)}">`;
            } else {
                shownCardImg.innerHTML = `<span style="color:#FFD700;font-size:16px;">${getCardDisplayName(currentShownCard)}</span>`;
            }
        }
    }
}

